-- WARNING: Running this script replaces every existing product in app_store.
-- It leaves users, orders, sessions, riders, and payout requests unchanged.
-- Image paths are local placeholders; replace them with your product photos in the admin.
-- Prices and stock are sample values in NGN and should be verified before sale.

begin;

insert into public.app_store (collection, records)
values ('products', '[]'::jsonb)
on conflict (collection) do nothing;

update public.app_store
set records = $products$
